import {createGame} from './game.mjs';
import {setupMap} from './map-interaction.mjs';
import {layoutLandmarks} from './landmark-layout.mjs';
const $=id=>document.getElementById(id),ns='http://www.w3.org/2000/svg';
let photos=[],geometry=[],landmarks=[],game,sound=false,audio,ready=false,mapReady=false,mapView,activeLandmark=null;
function svg(tag,attrs,parent){const el=document.createElementNS(ns,tag);for(const [k,v]of Object.entries(attrs))el.setAttribute(k,v);parent?.append(el);return el;}
function point(lat,lng){return mapView.camera.project(lat,lng);}
function drawMap(){if(mapView)mapView.render();}
function drawLandmarks(){
 const layer=$('landmarks'),camera=mapView.camera;
 if(!layer.children.length)for(const p of landmarks){
  const g=svg('g',{class:'landmark','data-landmark':p.id,role:'button',tabindex:'0','aria-label':p.name,'aria-pressed':'false'},layer);
  svg('path',{class:'landmark-leader',fill:'none',stroke:'#87927d','stroke-width':1,'pointer-events':'none'},g);
  svg('circle',{class:'landmark-anchor',r:2,fill:'#87927d','pointer-events':'none'},g);
  svg('rect',{class:'landmark-hit',fill:'transparent'},g);
  svg('image',{href:p.image,'aria-hidden':'true',class:'landmark-image','pointer-events':'none'},g);
  const label=svg('g',{class:'landmark-label','aria-hidden':'true'},g);
  svg('rect',{height:25,rx:3},label);const text=svg('text',{'text-anchor':'middle'},label);text.textContent=p.name;
  g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggleLandmark(p.id)}if(e.key==='Escape'){activeLandmark=null;drawLandmarks()}});
 }
 const size=camera.width<420?32:44;
 const placements=layoutLandmarks(landmarks.map(p=>({...p,anchor:point(p.lat,p.lng)})),camera.width,camera.height,size);
 for(const p of placements){
  const g=layer.querySelector(`[data-landmark="${p.id}"]`);g.style.display=p.hidden?'none':'';g.setAttribute('tabindex',p.hidden?'-1':'0');if(p.hidden)continue;
  const [ax,ay]=p.anchor;
  for(const el of [g.querySelector('.landmark-image'),g.querySelector('.landmark-hit')])for(const [key,value]of Object.entries({x:p.x,y:p.y,width:p.size,height:p.size}))el.setAttribute(key,value);
  const hit=g.querySelector('.landmark-hit'),hitSize=Math.max(44,p.size);hit.setAttribute('x',p.x-(hitSize-p.size)/2);hit.setAttribute('y',p.y-(hitSize-p.size)/2);hit.setAttribute('width',hitSize);hit.setAttribute('height',hitSize);
  const endX=Math.max(p.x,Math.min(p.x+p.size,ax)),endY=Math.max(p.y,Math.min(p.y+p.size,ay));
  g.querySelector('.landmark-leader').setAttribute('d',`M${ax} ${ay}L${endX} ${endY}`);
  g.querySelector('.landmark-anchor').setAttribute('cx',ax);g.querySelector('.landmark-anchor').setAttribute('cy',ay);
  const width=p.name.length*7.2+20,lx=Math.max(5,Math.min(camera.width-width-5,p.x+p.size/2-width/2)),ly=Math.min(camera.height-30,p.y+p.size+4);
  const label=g.querySelector('.landmark-label');label.querySelector('rect').setAttribute('x',lx);label.querySelector('rect').setAttribute('y',ly);label.querySelector('rect').setAttribute('width',width);label.querySelector('text').setAttribute('x',lx+width/2);label.querySelector('text').setAttribute('y',ly+17);
  g.classList.toggle('active',activeLandmark===p.id);g.setAttribute('aria-pressed',String(activeLandmark===p.id));
 }
}
function toggleLandmark(id){activeLandmark=activeLandmark===id?null:id;drawLandmarks();}
function mapTap(target){const dot=target.closest('[data-dot]'),landmark=target.closest('[data-landmark]');if(dot)guess(Number(dot.dataset.dot));else if(landmark)toggleLandmark(landmark.dataset.landmark);else {activeLandmark=null;drawLandmarks();}}
function drawMarkers(){if(!game||game.complete)return;$('markers').replaceChildren();$('connection').replaceChildren();const result=game.revealed?game.results.at(-1):null;
 if(result&&!result.correct){const a=point(game.photo.lat,game.photo.lng),p=photos.find(p=>p.id===result.picked),b=point(p.lat,p.lng);svg('path',{d:`M${b} L${a}`,stroke:'#ddfa45','stroke-width':2,'stroke-dasharray':'5 5',fill:'none'},$('connection'));}
 photos.forEach((p,i)=>{const [x,y]=point(p.lat,p.lng);const cls=result?(p.id===game.photo.id?' correct':p.id===result.picked?' chosen':' dim'):'';const g=svg('g',{transform:`translate(${x},${y})`,class:'dot'+cls,'data-dot':p.id,role:'button',tabindex:result||!ready?'-1':'0','aria-disabled':String(!!result||!ready),'aria-label':result?(p.id===game.photo.id?'Correct location':p.id===result.picked?'Your guess':'Other location'):`Choose location ${i+1}`},$('markers'));svg('circle',{r:23,class:'halo'},g);svg('circle',{r:10,class:'core'},g);if(result&&(p.id===game.photo.id||p.id===result.picked)){const t=svg('text',{y:0},g);t.textContent=p.id===game.photo.id?'✓':'·';}g.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();guess(p.id)}});});}
function progress(){ $('round-label').textContent=`ROUND ${String(Math.min(game.index+1,photos.length)).padStart(2,'0')} / ${String(photos.length).padStart(2,'0')}`;$('progress').innerHTML=Array.from({length:photos.length},(_,i)=>`<i class="${game.results[i]?(game.results[i].correct?'hit':'miss'):i===game.index?'current':''}"></i>`).join('');}
function startRound(){setMobileView('photo');ready=false;activeLandmark=null;if(mapView)mapView.camera.fit('central');document.body.classList.remove('success');$('photo-status').hidden=true;$('next').disabled=true;$('next-label').textContent='PICK A DOT';$('reaction').innerHTML='Where was this <em>taken?</em>';$('feedback').textContent='Pick a lime dot on the map.';$('photo-loading').hidden=false;$('photo-loading').textContent='LOADING…';$('photo').style.opacity='0';$('enlarge').disabled=true;
 $('photo').onload=()=>{ready=true;$('photo-loading').hidden=true;$('photo').style.opacity='1';$('enlarge').disabled=false;syncAction();drawMarkers()};$('photo').onerror=()=>{$('photo-loading').textContent='Photo could not load. Reload to try again.'};$('photo').alt=game.photo.title; $('photo').src=game.photo.image;progress();drawMap();}
function chime(correct){if(!sound)return;try{audio??=new AudioContext();audio.resume().catch(()=>{});[0,.09,.18].slice(0,correct?3:1).forEach((delay,i)=>{const o=audio.createOscillator(),v=audio.createGain();o.type='sine';o.frequency.value=correct?[440,554,740][i]:280;o.connect(v);v.connect(audio.destination);v.gain.setValueAtTime(.0001,audio.currentTime+delay);v.gain.exponentialRampToValueAtTime(.1,audio.currentTime+delay+.01);v.gain.exponentialRampToValueAtTime(.0001,audio.currentTime+delay+.25);o.start(audio.currentTime+delay);o.stop(audio.currentTime+delay+.3)})}catch{}}
function guess(id){if(!ready||!mapReady||game.revealed||game.complete)return;const r=game.guess(id);chime(r.correct);document.body.classList.toggle('success',r.correct);$('reaction').innerHTML=r.correct?'That’s <em>the spot.</em>':'Here’s <em>the spot.</em>';$('feedback').textContent=r.correct?'You found the right location.':`About ${r.meters>=1000?(r.meters/1000).toFixed(1)+' km':Math.round(r.meters/10)*10+' m'} away. Lime shows the photo’s location.`;$('photo-status').hidden=!r.correct;$('photo-status').textContent='YES!';$('next').disabled=false;$('next-label').textContent=game.index===photos.length-1?'SEE RESULTS':'NEXT PHOTO';progress();drawMarkers();$('next').focus({preventScroll:true});return r;}
function next(){if(!game.revealed||game.complete)return;if(game.next()){startRound();return}document.querySelector('.game-grid').hidden=true;document.querySelector('.action-bar').hidden=true;$('finish').hidden=false;const hits=game.results.filter(r=>r.correct).length;$('finish-copy').textContent=`${hits} of ${photos.length} locations found.`;$('recap').replaceChildren();for(const r of game.results){const p=photos.find(p=>p.id===r.id),f=document.createElement('figure'),im=document.createElement('img'),cap=document.createElement('figcaption');im.src=p.image;im.alt=p.title;cap.innerHTML=`${r.correct?'<b>✓ Found it</b>':'A new place'}`;f.append(im,cap);$('recap').append(f)}$('replay').focus();}
function syncAction(){if(!game||game.complete||game.revealed)return;$('next').disabled=!ready||!mapReady;$('next-label').textContent='PICK A DOT';}

matchMedia('(max-width:760px)').addEventListener('change',syncAction);
function setMobileView(view){document.body.dataset.mobileView=view;syncAction();document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.view===view)));if(view==='map'&&mapView)requestAnimationFrame(()=>{mapView.camera.resize($('map-wrap').clientWidth,$('map-wrap').clientHeight);mapView.render()});}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setMobileView(b.dataset.view));
$('next').onclick=()=>{if(!game.revealed){setMobileView('map');requestAnimationFrame(()=>{$('map').scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});$('map').focus({preventScroll:true});});return}next()};$('replay').onclick=()=>{game=createGame(photos);$('finish').hidden=true;document.querySelector('.game-grid').hidden=false;document.querySelector('.action-bar').hidden=false;startRound()};$('sound').onclick=()=>{sound=!sound;$('sound').setAttribute('aria-pressed',String(sound));$('sound').innerHTML=`SOUND ${sound?'ON':'OFF'} <span>↗</span>`;if(sound)chime(true)};
$('enlarge').onclick=()=>{$('large-photo').alt=game.photo.title;$('large-photo').src=game.photo.image;$('image-dialog').showModal()};document.querySelectorAll('dialog').forEach(d=>{d.querySelector('.close').onclick=()=>d.close();d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})});
try{const [pr,mr,lr]=await Promise.all([fetch('photos.json'),fetch('map.json'),fetch('landmarks.json')]);if(!pr.ok||!mr.ok||!lr.ok)throw Error('Content unavailable');photos=await pr.json();geometry=await mr.json();landmarks=await lr.json();mapReady=true;game=createGame(photos);mapView=setupMap({root:$('map'),geometry,locations:photos,landmarks,onChange:()=>{drawLandmarks();drawMarkers()},onTap:mapTap});startRound();
 const context=document.modelContext;if(context?.registerTool){for(const tool of [{name:'guess_graffiti_location',description:'Choose one anonymous map dot in the current round. Commits the guess and reveals the answer.',inputSchema:{type:'object',properties:{dot:{type:'integer',minimum:1,maximum:photos.length}},required:['dot'],additionalProperties:false},annotations:{readOnlyHint:false},execute:({dot})=>{if(!Number.isInteger(dot)||dot<1||dot>photos.length)throw Error(`Dot must be 1 to ${photos.length}`);if(!ready||game.revealed||game.complete)throw Error('Round is not accepting guesses');return guess(photos[dot-1].id)}},{name:'next_graffiti_round',description:'Advance after a revealed guess; after the final round show the session recap.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},execute:()=>{if(!game.revealed||game.complete)throw Error('No revealed round to advance');next();return {round:Math.min(game.index+1,photos.length),complete:game.complete}}}]){try{Promise.resolve(context.registerTool(tool)).catch(()=>{})}catch{}}}
}catch(e){$('photo-loading').textContent='Couldn’t load the archive. Please reload.';console.error(e)}
